// Roles and permissions for this app.
// Generated by tylix make:permissions. Yours to edit.
//
// Check anywhere on the server:
//   await permissions.can(req.user, 'posts.publish')
//   await permissions.for(user).assignRole('editor')
// Guard a route (app/routes/web.ts):
//   router.post('/api/posts', permissions.middleware('posts.create'), handler)
// In the browser, the signed-in user carries user.access, so pages check
// with can("posts.publish") and hasRole("admin") without a request.
import { Model } from '@tylix/orm'
import { createPermissions, ormStore } from '@tylix/permissions'

export const permissions = createPermissions({
  store: ormStore({ Model }),

  // Anyone with this role passes every check.
  superAdmin: 'super-admin',

  // Every signed-in user has these roles without being given them.
  defaultRoles: ['member'],

  // Resource rules: permissions.can(user, 'posts.update', post) asks the
  // rule; without a resource, only stored permissions count.
  rules: {
    'posts.update': ({ user, resource, granted }: any) =>
      granted || String(resource?.user_id) === String(user.id ?? user.userId),
  },
})

// The starting roles and permissions. PermissionSeeder syncs them (run
// "tylix db:seed" or "tylix permission:sync"); it only adds and updates,
// so roles you create in the admin page are kept.
//
// Grants can use wildcards ("posts.*", "posts.edit,delete", "*") and
// denies ("!posts.delete"), and a role can inherit other roles.
export const definition = {
  permissions: [
    // News & insights (the starter's posts, now staff-written content)
    { name: 'posts.view', description: 'See posts' },
    { name: 'posts.create', description: 'Write posts' },
    { name: 'posts.update', description: 'Edit any post' },
    { name: 'posts.delete', description: 'Delete any post' },
    { name: 'posts.publish', description: 'Publish posts' },
    { name: 'users.view', description: 'See the list of users' },
    { name: 'roles.manage', description: 'Create roles and give them to users' },

    // Barani Better Homes administration
    { name: 'admin.access', description: 'Open the administration dashboard' },
    { name: 'listings.view', description: 'See every listing, published or not' },
    { name: 'listings.manage', description: 'Create and edit Website-only listings (sales, land)' },
    { name: 'listings.feature', description: 'Feature listings and edit marketing details' },
    { name: 'enquiries.view', description: 'See enquiries' },
    { name: 'enquiries.manage', description: 'Answer, assign and close enquiries' },
    { name: 'viewings.manage', description: 'Confirm, reschedule and close viewing requests' },
    { name: 'applications.view', description: 'See rental and purchase applications' },
    { name: 'applications.manage', description: 'Review, approve and reject applications' },
    { name: 'customers.view', description: 'See customer accounts' },
    { name: 'agents.manage', description: 'Add and edit agents' },
    { name: 'content.manage', description: 'Edit site pages and homepage content' },
    { name: 'reports.view', description: 'See reports and analytics' },
    { name: 'integration.view', description: 'See HQ sync status and logs' },
    { name: 'integration.manage', description: 'Run an HQ sync by hand' },
    { name: 'settings.manage', description: 'Change platform settings' },
  ],
  roles: {
    'super-admin': { description: 'Passes every check', permissions: [] },
    admin: {
      description: 'Runs Barani Better Homes',
      inherits: ['agent', 'editor'],
      permissions: ['users.*', 'roles.manage', 'listings.*', 'agents.manage', 'reports.view', 'integration.*', 'settings.manage', 'customers.view'],
    },
    agent: {
      description: 'Handles enquiries, viewings and applications',
      inherits: ['member'],
      permissions: ['admin.access', 'listings.view', 'listings.feature', 'enquiries.*', 'viewings.manage', 'applications.*', 'customers.view'],
    },
    editor: {
      description: 'Writes news and edits site content',
      inherits: ['member'],
      permissions: ['admin.access', 'posts.*', 'content.manage', 'integration.view'],
    },
    // Customers. They read news but don't write it.
    member: { description: 'Every signed-in user', permissions: ['posts.view'] },
  },
}
